INSERT INTO public.bio_templates (npc_name,worldknowledge_tags,core,npc_static_bio,appearance,personality,relationships,occupation,skills,speechstyle,goals,voiceid,gender,race,refid) VALUES
('creature_abomination','fallout,creature,abomination','A warped FEV-mutated humanoid driven by hunger and territorial fury','Abominations are FEV-twisted humanoids with elongated limbs and hyperdeveloped musculature granting terrifying speed and reach. They hunt by scent and sound, preferring fresh meat but consuming carrion when desperate. Pack dynamics form around the strongest individual, with weaker members following dominant scents. Their warped vocal cords produce only shrieks and growls, though residual brain function suggests dim awareness of their former humanity. They kill anything that moves within their territory.','Stretched limbs disproportionate to a hunched torso, gray-green mottled skin stretched over swollen muscle, a head barely recognizable as once-human with a lipless mouth and milky eyes','Aggressive, territorial, and driven by constant hunger, with flashes of confused recognition when encountering normal humans','{"pack":"Follows the strongest; challenges the weak","humans":"Prey that sometimes smells wrong","other_mutants":"Competitors or packmates depending on size"}','Territorial predator','* Ambush hunting
